INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>CodeLens — Interactive Code Review</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">\n  <style>\n    :root {\n      --bg: #0B0F17;\n      --surface: #111827;\n      --elevated: #1A2233;\n      --border: #263045;\n      --text: #F3F4F6;\n      --muted: #9CA3AF;\n      --accent: #7C6CFF;\n      --accent-cyan: #22D3EE;\n      --sev-critical: #EF4444;\n      --sev-high: #F97316;\n      --sev-medium: #F59E0B;\n      --sev-low: #3B82F6;\n      --sev-info: #64748B;\n      --editor-size: 13px;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: \'Inter\', system-ui, sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n    body.compact { font-size: 13px; }\n    .mono { font-family: \'JetBrains Mono\', monospace; }\n\n    /* Header */\n    header {\n      background: rgba(17, 24, 39, 0.85);\n      backdrop-filter: blur(12px);\n      border-bottom: 1px solid var(--border);\n      padding: 0.75rem 1.5rem;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      position: sticky;\n      top: 0;\n      z-index: 40;\n    }\n    .brand { display: flex; align-items: center; gap: 0.6rem; font-weight: 700; font-size: 1.05rem; }\n    .brand-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 12px var(--accent); }\n    nav { display: flex; gap: 0.4rem; }\n    .nav-btn {\n      background: transparent; border: 1px solid transparent; color: var(--muted);\n      padding: 0.45rem 0.85rem; border-radius: 8px; cursor: pointer; font-size: 0.875rem; font-weight: 500;\n      transition: all 150ms ease;\n    }\n    .nav-btn:hover { color: var(--text); background: var(--elevated); }\n    .nav-btn.active { color: var(--text); background: rgba(124, 108, 255, 0.15); border-color: rgba(124, 108, 255, 0.4); }\n\n    .header-actions { display: flex; align-items: center; gap: 0.6rem; }\n    .kbd-hint {\n      font-size: 0.75rem; color: var(--muted); background: var(--elevated);\n      border: 1px solid var(--border); padding: 0.25rem 0.5rem; border-radius: 6px; cursor: pointer;\n    }\n    .btn {\n      background: var(--accent); color: #fff; border: none; padding: 0.5rem 1rem;\n      border-radius: 8px; font-weight: 600; font-size: 0.875rem; cursor: pointer;\n      display: inline-flex; align-items: center; gap: 0.4rem; transition: transform 150ms ease, opacity 150ms ease;\n    }\n    .btn:hover { transform: translateY(-1px); opacity: 0.95; }\n    .btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }\n    .btn-ghost { background: var(--elevated); border: 1px solid var(--border); color: var(--text); }\n    .btn-sm { padding: 0.3rem 0.65rem; font-size: 0.78rem; }\n\n    /* Main container */\n    main { flex: 1; padding: 1.25rem 1.5rem; max-width: 1440px; width: 100%; margin: 0 auto; }\n    .page { display: none; }\n    .page.active { display: block; animation: fadeIn 180ms ease; }\n    @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }\n\n    .glass-card {\n      background: rgba(17, 24, 39, 0.7);\n      backdrop-filter: blur(12px);\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 1rem;\n    }\n\n    /* Stepper */\n    .stepper { display: flex; gap: 0.5rem; margin-bottom: 1rem; flex-wrap: wrap; }\n    .step-pill {\n      flex: 1; min-width: 130px; padding: 0.55rem 0.75rem; border-radius: 8px;\n      background: var(--surface); border: 1px solid var(--border); font-size: 0.8rem;\n      display: flex; align-items: center; gap: 0.5rem; color: var(--muted); transition: all 200ms ease;\n    }\n    .step-pill.active { border-color: var(--accent); color: var(--text); background: rgba(124, 108, 255, 0.12); }\n    .step-pill.done { border-color: #10B981; color: #34D399; }\n    .step-dot { width: 8px; height: 8px; border-radius: 50%; background: currentColor; }\n\n    /* Workbench grid */\n    .workbench { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: 1rem; }\n    .workbench.stacked { grid-template-columns: 1fr; }\n    @media (max-width: 960px) { .workbench { grid-template-columns: 1fr; } }\n\n    .toolbar { display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; margin-bottom: 0.75rem; }\n    select, input[type="text"], input[type="password"], input[type="email"] {\n      background: var(--elevated); color: var(--text); border: 1px solid var(--border);\n      border-radius: 8px; padding: 0.45rem 0.7rem; font-size: 0.85rem; outline: none;\n    }\n    select:focus, input:focus, textarea:focus { border-color: var(--accent); }\n\n    textarea.code-editor {\n      width: 100%; min-height: 440px; background: #070A10; color: #E5E7EB;\n      border: 1px solid var(--border); border-radius: 10px; padding: 1rem;\n      font-family: \'JetBrains Mono\', monospace; font-size: var(--editor-size);\n      line-height: 1.55; resize: vertical; outline: none; tab-size: 4;\n    }\n\n    /* Dashboard summary row */\n    .summary-bar { display: flex; align-items: center; gap: 1rem; margin-bottom: 0.85rem; }\n    .score-ring {\n      width: 64px; height: 64px; border-radius: 50%;\n      background: conic-gradient(var(--accent) calc(var(--score, 0) * 1%), var(--elevated) 0);\n      display: grid; place-items: center; flex-shrink: 0;\n    }\n    .score-inner {\n      width: 50px; height: 50px; border-radius: 50%; background: var(--surface);\n      display: grid; place-items: center; font-weight: 700; font-size: 1rem;\n    }\n\n    /* Filter chips */\n    .chips { display: flex; gap: 0.4rem; flex-wrap: wrap; margin-bottom: 0.75rem; }\n    .chip {\n      padding: 0.25rem 0.6rem; border-radius: 999px; font-size: 0.75rem; font-weight: 600;\n      border: 1px solid var(--border); background: var(--elevated); color: var(--muted); cursor: pointer;\n    }\n    .chip.active { border-color: var(--accent); color: var(--text); background: rgba(124, 108, 255, 0.2); }\n\n    /* Finding cards */\n    .findings-list { display: flex; flex-direction: column; gap: 0.65rem; max-height: 460px; overflow-y: auto; padding-right: 4px; }\n    .finding-card {\n      background: var(--elevated); border: 1px solid var(--border); border-left: 4px solid var(--sev-info);\n      border-radius: 10px; padding: 0.85rem; transition: transform 150ms ease, box-shadow 150ms ease;\n    }\n    .finding-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.3); }\n    .sev-critical { border-left-color: var(--sev-critical); }\n    .sev-high { border-left-color: var(--sev-high); }\n    .sev-medium { border-left-color: var(--sev-medium); }\n    .sev-low { border-left-color: var(--sev-low); }\n\n    .badge {\n      display: inline-block; padding: 0.15rem 0.45rem; border-radius: 5px;\n      font-size: 0.7rem; font-weight: 700; text-transform: uppercase;\n    }\n    .badge-critical { background: rgba(239,68,68,0.18); color: #FCA5A5; }\n    .badge-high { background: rgba(249,115,22,0.18); color: #FDBA74; }\n    .badge-medium { background: rgba(245,158,11,0.18); color: #FCD34D; }\n    .badge-low { background: rgba(59,130,246,0.18); color: #93C5FD; }\n    .badge-info { background: rgba(100,116,139,0.2); color: #CBD5E1; }\n\n    /* Modal / Command Palette */\n    .modal-backdrop {\n      position: fixed; inset: 0; background: rgba(0,0,0,0.65); backdrop-filter: blur(4px);\n      display: none; place-items: center; z-index: 100;\n    }\n    .modal-backdrop.open { display: grid; }\n    .palette {\n      width: min(540px, 92vw); background: var(--surface); border: 1px solid var(--border);\n      border-radius: 14px; overflow: hidden; box-shadow: 0 24px 64px rgba(0,0,0,0.6);\n    }\n    .palette input { width: 100%; border: none; border-bottom: 1px solid var(--border); border-radius: 0; padding: 0.9rem 1rem; font-size: 0.95rem; background: var(--surface); }\n    .palette-list { max-height: 280px; overflow-y: auto; padding: 0.4rem; }\n    .palette-item {\n      padding: 0.6rem 0.85rem; border-radius: 8px; cursor: pointer; display: flex;\n      justify-content: space-between; font-size: 0.875rem;\n    }\n    .palette-item:hover { background: rgba(124, 108, 255, 0.16); }\n\n    /* Toast */\n    .toast {\n      position: fixed; bottom: 1.25rem; right: 1.25rem; background: var(--elevated);\n      border: 1px solid var(--accent); padding: 0.7rem 1rem; border-radius: 10px;\n      font-size: 0.85rem; z-index: 120; display: none; box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n    }\n    .toast.show { display: block; animation: fadeIn 150ms ease; }\n    table { width: 100%; border-collapse: collapse; font-size: 0.875rem; }\n    th, td { text-align: left; padding: 0.65rem 0.75rem; border-bottom: 1px solid var(--border); }\n    th { color: var(--muted); font-weight: 600; }\n  </style>\n</head>\n<body>\n  <header>\n    <div class="brand">\n      <span class="brand-dot"></span>\n      <span>CodeLens</span>\n    </div>\n    <nav aria-label="Main navigation">\n      <button class="nav-btn active" data-page="workbench">Workbench</button>\n      <button class="nav-btn" data-page="history">History</button>\n      <button class="nav-btn" data-page="playground">API Playground</button>\n      <button class="nav-btn" data-page="keys">API Keys</button>\n      <button class="nav-btn" data-page="settings">Settings</button>\n    </nav>\n    <div class="header-actions">\n      <button class="kbd-hint" onclick="togglePalette()" title="Command Palette">⌘K</button>\n      <span id="authBadge" style="font-size:0.8rem;color:var(--muted);">Guest</span>\n      <button class="btn btn-ghost btn-sm" id="authModalBtn" onclick="openAuthModal()">Sign In</button>\n    </div>\n  </header>\n\n  <main>\n    <!-- WORKBENCH PAGE -->\n    <section id="page-workbench" class="page active">\n      <div class="stepper" id="stepper" aria-live="polite">\n        <div class="step-pill" data-step="0"><span class="step-dot"></span>Parsing</div>\n        <div class="step-pill" data-step="1"><span class="step-dot"></span>Static checks</div>\n        <div class="step-pill" data-step="2"><span class="step-dot"></span>AI analysis</div>\n        <div class="step-pill" data-step="3"><span class="step-dot"></span>Merging results</div>\n        <div class="step-pill" data-step="4"><span class="step-dot"></span>Generating fixes</div>\n      </div>\n\n      <div class="workbench" id="workbenchGrid">\n        <!-- Left: Code Editor -->\n        <div class="glass-card">\n          <div class="toolbar">\n            <select id="languageSelect" aria-label="Language">\n              <option value="python">Python</option>\n              <option value="javascript">JavaScript</option>\n              <option value="typescript">TypeScript</option>\n              <option value="php">PHP</option>\n              <option value="cpp">C++</option>\n              <option value="java">Java</option>\n              <option value="go">Go</option>\n              <option value="sql">SQL</option>\n            </select>\n            <select id="sampleSelect" onchange="loadSample(this.value)" aria-label="Load sample code">\n              <option value="">Load Sample Code...</option>\n              <option value="python">Buggy Python (SQLi + Bare Except)</option>\n              <option value="php">SQL Injection in PHP</option>\n              <option value="cpp">Memory Leak & Overflow in C++</option>\n            </select>\n            <label class="btn btn-ghost btn-sm" style="cursor:pointer;">\n              Upload File\n              <input type="file" hidden onchange="handleFileUpload(event)" />\n            </label>\n            <button class="btn" id="runBtn" onclick="runReview()" style="margin-left:auto;">\n              ▶ Run Review (Ctrl+Enter)\n            </button>\n          </div>\n          <textarea id="codeEditor" class="code-editor" spellcheck="false" placeholder="Paste or drop your code here..."></textarea>\n        </div>\n\n        <!-- Right: Findings & Dashboard -->\n        <div class="glass-card">\n          <div class="summary-bar">\n            <div class="score-ring" id="scoreRing" style="--score: 0;">\n              <div class="score-inner" id="scoreText">—</div>\n            </div>\n            <div>\n              <div style="font-weight:700;font-size:1rem;" id="summaryTitle">Ready to review</div>\n              <div style="font-size:0.82rem;color:var(--muted);margin-top:0.2rem;" id="summaryDesc">\n                Submit code to stream live security, quality &amp; performance findings.\n              </div>\n            </div>\n          </div>\n\n          <div class="toolbar">\n            <input type="text" id="searchFindings" placeholder="Search findings..." oninput="renderFindings()" style="flex:1;" />\n            <select id="sortFindings" onchange="renderFindings()">\n              <option value="severity">Sort: Severity</option>\n              <option value="line">Sort: Line #</option>\n            </select>\n          </div>\n\n          <div class="chips" id="sevChips">\n            <button class="chip active" data-sev="all" onclick="setSevFilter(\'all\')">All (<span id="cnt-all">0</span>)</button>\n            <button class="chip" data-sev="critical" onclick="setSevFilter(\'critical\')">Critical (<span id="cnt-critical">0</span>)</button>\n            <button class="chip" data-sev="high" onclick="setSevFilter(\'high\')">High (<span id="cnt-high">0</span>)</button>\n            <button class="chip" data-sev="medium" onclick="setSevFilter(\'medium\')">Medium (<span id="cnt-medium">0</span>)</button>\n            <button class="chip" data-sev="low" onclick="setSevFilter(\'low\')">Low (<span id="cnt-low">0</span>)</button>\n          </div>\n\n          <div class="findings-list" id="findingsList">\n            <div style="text-align:center;color:var(--muted);padding:2.5rem 1rem;font-size:0.875rem;">\n              No findings yet. Pick a sample or paste code and click <strong>Run Review</strong>.\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- HISTORY PAGE -->\n    <section id="page-history" class="page">\n      <div class="glass-card">\n        <div class="toolbar" style="justify-content:space-between;">\n          <h2>Review History</h2>\n          <button class="btn btn-ghost btn-sm" onclick="loadHistory()">↻ Refresh</button>\n        </div>\n        <table>\n          <thead>\n            <tr><th>ID</th><th>Language</th><th>Status</th><th>Score</th><th>Summary</th><th>Action</th></tr>\n          </thead>\n          <tbody id="historyBody"></tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- API PLAYGROUND PAGE -->\n    <section id="page-playground" class="page">\n      <div class="glass-card">\n        <h2 style="margin-bottom:0.85rem;">API Playground</h2>\n        <div class="toolbar">\n          <select id="pgEndpoint">\n            <option value="GET /api/health">GET /api/health</option>\n            <option value="GET /api/reviews">GET /api/reviews</option>\n            <option value="POST /api/reviews">POST /api/reviews</option>\n          </select>\n          <button class="btn" onclick="sendPlayground()">Send Request</button>\n          <span id="pgStatus" style="font-size:0.85rem;color:var(--accent-cyan);"></span>\n        </div>\n        <div class="workbench" style="margin-top:0.5rem;">\n          <div>\n            <div style="font-size:0.8rem;color:var(--muted);margin-bottom:0.35rem;">Request Body (JSON)</div>\n            <textarea id="pgBody" class="code-editor" style="min-height:220px;">{\n  "language": "python",\n  "code": "eval(input())"\n}</textarea>\n          </div>\n          <div>\n            <div style="font-size:0.8rem;color:var(--muted);margin-bottom:0.35rem;">Response</div>\n            <textarea id="pgResponse" class="code-editor" style="min-height:220px;" readonly></textarea>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- API KEYS PAGE -->\n    <section id="page-keys" class="page">\n      <div class="glass-card">\n        <h2 style="margin-bottom:0.5rem;">API Keys</h2>\n        <p style="font-size:0.85rem;color:var(--muted);margin-bottom:1rem;">Sign in to create and manage API keys for CI/CD integrations.</p>\n        <div class="toolbar">\n          <input type="text" id="newKeyName" placeholder="Key name (e.g. GitHub Actions)" />\n          <button class="btn" onclick="createApiKey()">+ Create Key</button>\n        </div>\n        <div id="createdKeyBanner" style="display:none;background:rgba(16,185,129,0.12);border:1px solid #10B981;padding:0.75rem;border-radius:8px;margin-bottom:1rem;font-size:0.85rem;"></div>\n        <table>\n          <thead><tr><th>Name</th><th>Prefix</th><th>Created</th><th>Action</th></tr></thead>\n          <tbody id="keysBody"></tbody>\n        </table>\n      </div>\n    </section>\n\n    <!-- SETTINGS PAGE -->\n    <section id="page-settings" class="page">\n      <div class="glass-card" style="max-width:560px;">\n        <h2 style="margin-bottom:1rem;">Personalisation Settings</h2>\n        <div style="display:flex;flex-direction:column;gap:1rem;">\n          <label style="display:flex;justify-content:space-between;align-items:center;">\n            <span>UI Density</span>\n            <select id="prefDensity" onchange="savePrefs()">\n              <option value="comfortable">Comfortable</option>\n              <option value="compact">Compact</option>\n            </select>\n          </label>\n          <label style="display:flex;justify-content:space-between;align-items:center;">\n            <span>Editor Font Size</span>\n            <select id="prefFontSize" onchange="savePrefs()">\n              <option value="12px">12px</option>\n              <option value="13px" selected>13px</option>\n              <option value="15px">15px</option>\n              <option value="17px">17px</option>\n            </select>\n          </label>\n          <label style="display:flex;justify-content:space-between;align-items:center;">\n            <span>Split View Layout</span>\n            <select id="prefSplit" onchange="savePrefs()">\n              <option value="side">Side-by-Side</option>\n              <option value="stacked">Stacked</option>\n            </select>\n          </label>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- COMMAND PALETTE -->\n  <div class="modal-backdrop" id="paletteModal" onclick="if(event.target===this)togglePalette()">\n    <div class="palette">\n      <input type="text" id="paletteInput" placeholder="Type a command..." oninput="filterPalette()" />\n      <div class="palette-list" id="paletteList"></div>\n    </div>\n  </div>\n\n  <!-- AUTH MODAL -->\n  <div class="modal-backdrop" id="authModal" onclick="if(event.target===this)closeAuthModal()">\n    <div class="palette" style="padding:1.25rem;width:min(380px,92vw);">\n      <h3 style="margin-bottom:0.85rem;">Sign In / Register</h3>\n      <div style="display:flex;flex-direction:column;gap:0.65rem;">\n        <input type="email" id="authEmail" placeholder="Email address" />\n        <input type="password" id="authPassword" placeholder="Password" />\n        <div style="display:flex;gap:0.5rem;margin-top:0.25rem;">\n          <button class="btn" style="flex:1;" onclick="submitAuth(\'login\')">Sign In</button>\n          <button class="btn btn-ghost" style="flex:1;" onclick="submitAuth(\'register\')">Register</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class="toast" id="toast"></div>\n\n  <script>\n    const SAMPLES = {\n      python: `import sqlite3\\n\\ndef get_user(username):\\n    conn = sqlite3.connect("users.db")\\n    cursor = conn.cursor()\\n    query = "SELECT * FROM users WHERE username = \'" + username + "\'"\\n    cursor.execute(query)\\n    return cursor.fetchone()\\n\\ndef divide(a, b):\\n    try:\\n        return a / b\\n    except:\\n        pass\\n\\npassword = "hunter2"\\nprint(password)`,\n      php: `<?php\\n$id = $_GET[\'id\'];\\n$result = mysqli_query($conn, "SELECT * FROM products WHERE id = $id");\\n$password = md5($_POST[\'password\']);\\necho $result;\\n?>`,\n      cpp: `#include <iostream>\\nvoid leak() {\\n    int* p = new int[100];\\n}\\nint main() {\\n    int arr[5];\\n    arr[10] = 42;\\n    leak();\\n    return 0;\\n}`\n    };\n\n    let currentFindings = [];\n    let sevFilter = \'all\';\n    let token = localStorage.getItem(\'cs_token\') || \'\';\n\n    // Navigation\n    document.querySelectorAll(\'.nav-btn\').forEach(btn => {\n      btn.addEventListener(\'click\', () => switchPage(btn.dataset.page));\n    });\n\n    function switchPage(page) {\n      document.querySelectorAll(\'.nav-btn\').forEach(b => b.classList.toggle(\'active\', b.dataset.page === page));\n      document.querySelectorAll(\'.page\').forEach(p => p.classList.toggle(\'active\', p.id === \'page-\' + page));\n      if (page === \'history\') loadHistory();\n      if (page === \'keys\') loadKeys();\n    }\n\n    function showToast(msg) {\n      const t = document.getElementById(\'toast\');\n      t.textContent = msg;\n      t.classList.add(\'show\');\n      setTimeout(() => t.classList.remove(\'show\'), 3000);\n    }\n\n    function loadSample(lang) {\n      if (!lang) return;\n      document.getElementById(\'languageSelect\').value = lang;\n      document.getElementById(\'codeEditor\').value = SAMPLES[lang] || \'\';\n      showToast(\'Loaded \' + lang + \' sample\');\n    }\n\n    function handleFileUpload(e) {\n      const file = e.target.files[0];\n      if (!file) return;\n      const reader = new FileReader();\n      reader.onload = ev => {\n        document.getElementById(\'codeEditor\').value = ev.target.result;\n        showToast(\'Loaded \' + file.name);\n      };\n      reader.readAsText(file);\n    }\n\n    async function runReview() {\n      const code = document.getElementById(\'codeEditor\').value.trim();\n      const language = document.getElementById(\'languageSelect\').value;\n      if (!code) return showToast(\'Please paste some code first\');\n\n      const btn = document.getElementById(\'runBtn\');\n      btn.disabled = true;\n      currentFindings = [];\n      renderFindings();\n      updateStepper(-1);\n      document.getElementById(\'summaryTitle\').textContent = \'Running analysis...\';\n      document.getElementById(\'summaryDesc\').textContent = \'Streaming live progress and findings from Gemini...\';\n      document.getElementById(\'scoreText\').textContent = \'...\';\n\n      try {\n        const headers = { \'Content-Type\': \'application/json\' };\n        if (token) headers[\'Authorization\'] = \'Bearer \' + token;\n        const res = await fetch(\'/api/reviews\', {\n          method: \'POST\', headers, body: JSON.stringify({ code, language })\n        });\n        const data = await res.json();\n        if (data.status === \'completed\') {\n          updateStepper(5);\n          currentFindings = data.findings || [];\n          renderFindings();\n          document.getElementById(\'scoreText\').textContent = data.score ?? 50;\n          document.getElementById(\'scoreRing\').style.setProperty(\'--score\', data.score ?? 50);\n          document.getElementById(\'summaryTitle\').textContent = \'Review Complete\';\n          document.getElementById(\'summaryDesc\').textContent = data.summary || \'Analysis finished.\';\n          btn.disabled = false;\n          return;\n        }\n        const es = new EventSource(data.stream_url);\n\n        es.onmessage = (ev) => {\n          const msg = JSON.parse(ev.data);\n          if (msg.type === \'progress\') {\n            updateStepper(msg.index);\n          } else if (msg.type === \'finding\') {\n            currentFindings.push(msg);\n            renderFindings();\n          } else if (msg.type === \'complete\') {\n            updateStepper(5);\n            document.getElementById(\'scoreText\').textContent = msg.score;\n            document.getElementById(\'scoreRing\').style.setProperty(\'--score\', msg.score);\n            document.getElementById(\'summaryTitle\').textContent = \'Review Complete\';\n            document.getElementById(\'summaryDesc\').textContent = msg.summary || \'Analysis finished.\';\n            btn.disabled = false;\n            es.close();\n          } else if (msg.type === \'error\') {\n            showToast(\'Error: \' + msg.message);\n            document.getElementById(\'summaryTitle\').textContent = \'Review Failed\';\n            document.getElementById(\'summaryDesc\').textContent = msg.message;\n            btn.disabled = false;\n            es.close();\n          }\n        };\n        es.onerror = () => { btn.disabled = false; es.close(); };\n      } catch (err) {\n        showToast(\'Failed to start review\');\n        btn.disabled = false;\n      }\n    }\n\n    function updateStepper(activeIdx) {\n      document.querySelectorAll(\'#stepper .step-pill\').forEach((el, idx) => {\n        el.classList.remove(\'active\', \'done\');\n        if (idx < activeIdx) el.classList.add(\'done\');\n        else if (idx === activeIdx) el.classList.add(\'active\');\n      });\n    }\n\n    function setSevFilter(sev) {\n      sevFilter = sev;\n      document.querySelectorAll(\'#sevChips .chip\').forEach(c => c.classList.toggle(\'active\', c.dataset.sev === sev));\n      renderFindings();\n    }\n\n    function renderFindings() {\n      const counts = { all: currentFindings.length, critical: 0, high: 0, medium: 0, low: 0 };\n      currentFindings.forEach(f => { if (counts[f.severity] !== undefined) counts[f.severity]++; });\n      Object.entries(counts).forEach(([k, v]) => {\n        const el = document.getElementById(\'cnt-\' + k);\n        if (el) el.textContent = v;\n      });\n\n      const query = document.getElementById(\'searchFindings\').value.toLowerCase();\n      const sortBy = document.getElementById(\'sortFindings\').value;\n      const rank = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };\n\n      let filtered = currentFindings.filter(f => {\n        if (sevFilter !== \'all\' && f.severity !== sevFilter) return false;\n        if (query && !(f.title + \' \' + f.description).toLowerCase().includes(query)) return false;\n        return true;\n      });\n\n      filtered.sort((a, b) => sortBy === \'line\'\n        ? (a.line_start || 9999) - (b.line_start || 9999)\n        : (rank[a.severity] ?? 5) - (rank[b.severity] ?? 5));\n\n      const list = document.getElementById(\'findingsList\');\n      if (!filtered.length) {\n        list.innerHTML = \'<div style="text-align:center;color:var(--muted);padding:2rem;font-size:0.85rem;">No matching findings.</div>\';\n        return;\n      }\n\n      list.innerHTML = filtered.map(f => `\n        <div class="finding-card sev-${f.severity || \'info\'}">\n          <div style="display:flex;justify-content:space-between;align-items:center;gap:0.5rem;margin-bottom:0.35rem;">\n            <span style="font-weight:600;font-size:0.9rem;">${escapeHtml(f.title || \'Issue\')}</span>\n            <span class="badge badge-${f.severity || \'info\'}">${escapeHtml(f.severity || \'info\')}</span>\n          </div>\n          <div style="font-size:0.78rem;color:var(--accent-cyan);margin-bottom:0.4rem;">\n            ${f.line_start ? \'Line \' + f.line_start : \'General\'} · ${escapeHtml(f.category || \'quality\')}\n          </div>\n          <p style="font-size:0.83rem;color:#D1D5DB;line-height:1.45;margin-bottom:0.5rem;">${escapeHtml(f.description || \'\')}</p>\n          ${f.fix ? `<div class="mono" style="font-size:0.78rem;background:#0B0F17;padding:0.5rem;border-radius:6px;border:1px solid var(--border);color:#A7F3D0;">Fix: ${escapeHtml(f.fix)}</div>` : \'\'}\n        </div>\n      `).join(\'\');\n    }\n\n    function escapeHtml(s) {\n      return String(s).replace(/[&<>"\']/g, m => ({ \'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\' }[m]));\n    }\n\n    // History\n    async function loadHistory() {\n      const headers = token ? { \'Authorization\': \'Bearer \' + token } : {};\n      const res = await fetch(\'/api/reviews\', { headers });\n      const rows = await res.json();\n      document.getElementById(\'historyBody\').innerHTML = rows.map(r => `\n        <tr>\n          <td class="mono" style="font-size:0.78rem;">${r.id.slice(0, 8)}</td>\n          <td>${escapeHtml(r.language)}</td>\n          <td>${escapeHtml(r.status)}</td>\n          <td>${r.score ?? \'—\'}</td>\n          <td style="max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(r.summary || \'\')}</td>\n          <td><button class="btn btn-ghost btn-sm" onclick="openReview(\'${r.id}\')">View</button></td>\n        </tr>\n      `).join(\'\') || \'<tr><td colspan="6" style="color:var(--muted);text-align:center;">No reviews yet.</td></tr>\';\n    }\n\n    async function openReview(id) {\n      const res = await fetch(\'/api/reviews/\' + id);\n      const data = await res.json();\n      currentFindings = data.findings || [];\n      document.getElementById(\'scoreText\').textContent = data.score ?? \'—\';\n      document.getElementById(\'scoreRing\').style.setProperty(\'--score\', data.score || 0);\n      document.getElementById(\'summaryTitle\').textContent = \'Loaded Review\';\n      document.getElementById(\'summaryDesc\').textContent = data.summary || \'\';\n      renderFindings();\n      switchPage(\'workbench\');\n    }\n\n    // Playground\n    async function sendPlayground() {\n      const [method, path] = document.getElementById(\'pgEndpoint\').value.split(\' \');\n      const opts = { method, headers: { \'Content-Type\': \'application/json\' } };\n      if (token) opts.headers[\'Authorization\'] = \'Bearer \' + token;\n      if (method === \'POST\') opts.body = document.getElementById(\'pgBody\').value;\n      const t0 = performance.now();\n      const res = await fetch(path, opts);\n      const ms = Math.round(performance.now() - t0);\n      document.getElementById(\'pgStatus\').textContent = `${res.status} ${res.statusText} · ${ms} ms`;\n      const text = await res.text();\n      try { document.getElementById(\'pgResponse\').value = JSON.stringify(JSON.parse(text), null, 2); }\n      catch { document.getElementById(\'pgResponse\').value = text; }\n    }\n\n    // Auth\n    function openAuthModal() { document.getElementById(\'authModal\').classList.add(\'open\'); }\n    function closeAuthModal() { document.getElementById(\'authModal\').classList.remove(\'open\'); }\n    async function submitAuth(mode) {\n      const email = document.getElementById(\'authEmail\').value;\n      const password = document.getElementById(\'authPassword\').value;\n      const res = await fetch(\'/api/auth/\' + mode, {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ email, password })\n      });\n      const data = await res.json();\n      if (!res.ok) return showToast(data.detail || \'Auth failed\');\n      token = data.access_token;\n      localStorage.setItem(\'cs_token\', token);\n      document.getElementById(\'authBadge\').textContent = data.user.email;\n      closeAuthModal();\n      showToast(\'Signed in as \' + data.user.email);\n    }\n\n    // API Keys\n    async function loadKeys() {\n      if (!token) return;\n      const res = await fetch(\'/api/api-keys\', { headers: { \'Authorization\': \'Bearer \' + token } });\n      if (!res.ok) return;\n      const keys = await res.json();\n      document.getElementById(\'keysBody\').innerHTML = keys.map(k => `\n        <tr>\n          <td>${escapeHtml(k.name)}</td>\n          <td class="mono">${escapeHtml(k.prefix)}...</td>\n          <td>${new Date(k.created_at).toLocaleDateString()}</td>\n          <td><button class="btn btn-ghost btn-sm" onclick="revokeKey(\'${k.id}\')">Revoke</button></td>\n        </tr>\n      `).join(\'\');\n    }\n    async function createApiKey() {\n      if (!token) return openAuthModal();\n      const name = document.getElementById(\'newKeyName\').value || \'Default Key\';\n      const res = await fetch(\'/api/api-keys\', {\n        method: \'POST\', headers: { \'Content-Type\': \'application/json\', \'Authorization\': \'Bearer \' + token },\n        body: JSON.stringify({ name })\n      });\n      const data = await res.json();\n      const banner = document.getElementById(\'createdKeyBanner\');\n      banner.style.display = \'block\';\n      banner.innerHTML = `New key (copy now, shown once): <code class="mono">${data.key}</code>`;\n      loadKeys();\n    }\n    async function revokeKey(id) {\n      await fetch(\'/api/api-keys/\' + id, { method: \'DELETE\', headers: { \'Authorization\': \'Bearer \' + token } });\n      loadKeys();\n    }\n\n    // Settings\n    function savePrefs() {\n      const prefs = {\n        density: document.getElementById(\'prefDensity\').value,\n        fontSize: document.getElementById(\'prefFontSize\').value,\n        split: document.getElementById(\'prefSplit\').value\n      };\n      localStorage.setItem(\'cs_prefs\', JSON.stringify(prefs));\n      applyPrefs(prefs);\n    }\n    function applyPrefs(prefs) {\n      document.body.classList.toggle(\'compact\', prefs.density === \'compact\');\n      document.documentElement.style.setProperty(\'--editor-size\', prefs.fontSize || \'13px\');\n      document.getElementById(\'workbenchGrid\').classList.toggle(\'stacked\', prefs.split === \'stacked\');\n    }\n\n    // Command Palette\n    const COMMANDS = [\n      { label: \'Run Code Review\', hint: \'Ctrl+Enter\', action: runReview },\n      { label: \'Go to Workbench\', hint: \'Page\', action: () => switchPage(\'workbench\') },\n      { label: \'Go to History\', hint: \'Page\', action: () => switchPage(\'history\') },\n      { label: \'Go to API Playground\', hint: \'Page\', action: () => switchPage(\'playground\') },\n      { label: \'Go to API Keys\', hint: \'Page\', action: () => switchPage(\'keys\') },\n      { label: \'Go to Settings\', hint: \'Page\', action: () => switchPage(\'settings\') },\n      { label: \'Load Buggy Python Sample\', hint: \'Sample\', action: () => loadSample(\'python\') }\n    ];\n    function togglePalette() {\n      const m = document.getElementById(\'paletteModal\');\n      m.classList.toggle(\'open\');\n      if (m.classList.contains(\'open\')) {\n        document.getElementById(\'paletteInput\').value = \'\';\n        filterPalette();\n        document.getElementById(\'paletteInput\').focus();\n      }\n    }\n    function filterPalette() {\n      const q = document.getElementById(\'paletteInput\').value.toLowerCase();\n      const list = document.getElementById(\'paletteList\');\n      list.innerHTML = \'\';\n      COMMANDS.filter(c => c.label.toLowerCase().includes(q)).forEach(c => {\n        const div = document.createElement(\'div\');\n        div.className = \'palette-item\';\n        div.innerHTML = `<span>${c.label}</span><span style="color:var(--muted);font-size:0.78rem;">${c.hint}</span>`;\n        div.onclick = () => { togglePalette(); c.action(); };\n        list.appendChild(div);\n      });\n    }\n\n    document.addEventListener(\'keydown\', e => {\n      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === \'k\') { e.preventDefault(); togglePalette(); }\n      if ((e.ctrlKey || e.metaKey) && e.key === \'Enter\') { e.preventDefault(); runReview(); }\n    });\n\n    // Init\n    (async function init() {\n      const saved = JSON.parse(localStorage.getItem(\'cs_prefs\') || \'{}\');\n      if (saved.density) document.getElementById(\'prefDensity\').value = saved.density;\n      if (saved.fontSize) document.getElementById(\'prefFontSize\').value = saved.fontSize;\n      if (saved.split) document.getElementById(\'prefSplit\').value = saved.split;\n      applyPrefs(saved);\n      loadSample(\'python\');\n      if (token) {\n        const res = await fetch(\'/api/auth/me\', { headers: { \'Authorization\': \'Bearer \' + token } });\n        if (res.ok) { const u = await res.json(); document.getElementById(\'authBadge\').textContent = u.email; }\n      }\n    })();\n  </script>\n</body>\n</html>\n'
